import re, subprocess
from pathlib import Path
text=subprocess.check_output(['git','log','upstream/branch-3.4','--pretty=%H\t%s'], text=True)
commits=[]
for line in text.splitlines():
    if not line.strip():
        continue
    h,s=line.split('\t',1)
    m=re.search(r'\b([A-Z]+-\d+)\b', s)
    jira=m.group(1) if m else None
    commits.append((jira,h,s))
byjira={}
for jira,h,s in commits:
    if jira:
        byjira.setdefault(jira,[]).append((h,s))
reqs=[]
for p in sorted(Path('requirements').glob('*.yaml')):
    if p.name == '.rename_map.json':
        continue
    t=p.read_text(errors='ignore')
    m=re.search(r"^title:\s*['\"]?([^\n]+)", t, re.M)
    title=m.group(1).strip() if m else ''
    j=re.search(r'\b([A-Z]+-\d+)\b', title)
    jira=j.group(1) if j else None
    reqs.append((p.stem,jira,title))
amb=[]
for slug,jira,title in reqs:
    cs=byjira.get(jira,[])
    if len(cs)>1:
        amb.append((slug,jira,title,cs))
print('ambiguous_count',len(amb))
for slug,jira,title,cs in amb:
    print(f'\n{slug}\t{jira}\t{len(cs)}\t{title}')
    for h,s in cs[:12]:
        print(' ',h[:10],s)
